import{_ as e,o as a,c as o,a2 as r}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"方案介绍","description":"","frontmatter":{},"headers":[],"relativePath":"web/form-page/auto-assignment/populate-fields-after-order-selection/solution-overview.md","filePath":"web/form-page/auto-assignment/populate-fields-after-order-selection/solution-overview.md"}'),d={name:"web/form-page/auto-assignment/populate-fields-after-order-selection/solution-overview.md"};function i(l,t,h,n,s,p){return a(),o("div",null,[...t[0]||(t[0]=[r('<h1 id="方案介绍" tabindex="-1">方案介绍 <a class="header-anchor" href="#方案介绍" aria-label="Permalink to &quot;方案介绍&quot;">​</a></h1><h2 id="方案概述" tabindex="-1">方案概述 <a class="header-anchor" href="#方案概述" aria-label="Permalink to &quot;方案概述&quot;">​</a></h2><p>本方案通过在表单页面（EntityForm）中进行组件级扩展实现。在主表字段中监听“原始订单”字段的取值变化，当用户选择订单后，通过事件绑定触发自定义逻辑，调用接口获取原订单的主表和明细数据，并将结果自动回填至当前变更单表单中。</p><h2 id="扩展组件" tabindex="-1">扩展组件 <a class="header-anchor" href="#扩展组件" aria-label="Permalink to &quot;扩展组件&quot;">​</a></h2><table tabindex="0"><thead><tr><th>终端</th><th>扩展对象</th><th>扩展页面</th><th>扩展区域</th><th>扩展组件</th><th>扩展功能</th></tr></thead><tbody><tr><td>网页端/移动端</td><td>订单变更单</td><td>表单页</td><td>主表单</td><td>字段</td><td>在“原始订单”字段选择数据后，自动填充“客户名称”、“订单总金额”及对应的订单明细数据</td></tr></tbody></table><h2 id="功能设计" tabindex="-1">功能设计 <a class="header-anchor" href="#功能设计" aria-label="Permalink to &quot;功能设计&quot;">​</a></h2><p><strong>交互逻辑</strong>：</p><ol><li><p>选择原始订单</p><p>用户在订单变更单表单页中选择“原始订单”字段，系统监听字段变更事件。</p></li><li><p>触发扩展逻辑</p><p>触发 onChange 扩展逻辑，获取原订单的主表字段及明细信息。</p></li><li><p>主表字段回填</p><p>将原订单的客户名称、订单总金额主表字段填充到当前变更单的对应字段中。</p></li><li><p>校验带出条件</p><p>检测“是否带出明细”字段的状态，判断是否需要同步原订单的明细数据。</p></li><li><p>用户操作与保存</p><p>用户可在带出结果的基础上，对字段内容进行修改、补充或直接保存变更单数据。</p></li></ol><h2 id="使用的-nex-扩展能力" tabindex="-1">使用的 NEX 扩展能力 <a class="header-anchor" href="#使用的-nex-扩展能力" aria-label="Permalink to &quot;使用的 NEX 扩展能力&quot;">​</a></h2><table tabindex="0"><thead><tr><th>功能点</th><th>扩展能力类别</th><th>属性/函数/事件</th><th>说明</th><th>示例值/使用方式</th></tr></thead><tbody><tr><td>字段值变更后执行自动填充逻辑</td><td>事件绑定</td><td>事件：onChange</td><td>执行“原始订单”字段值填充后，自动获取关联的订单信息，并将对应的字段值及明细数据同步填充至变更单中</td><td>onChange: (e) =&gt; { ... }</td></tr></tbody></table><h2 id="使用的其他能力" tabindex="-1">使用的其他能力 <a class="header-anchor" href="#使用的其他能力" aria-label="Permalink to &quot;使用的其他能力&quot;">​</a></h2><p>无</p>',12)])])}const b=e(d,[["render",i]]);export{u as __pageData,b as default};
